{
  "candidate": "cand_0001",
  "headline": "Seed: create airline capability — sharpen policy with procedures/worked-examples/checklists for a mid-capability reader, add a deterministic baggage-allowance compute tool and enriched recovery errors. All additive/error-path-only so the single passing val task (8) is unchanged.",
  "clusters": [
    {"id": "A", "name": "Baggage allowance math", "detail": "Mid model mis-derives free checked-bag allowance (membership x cabin x passengers) and thus nonfree_baggages, producing a wrong $50/bag fee, wrong DB state, or a payment-amount mismatch.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "CAPABILITY-GAP"},
    {"id": "B", "name": "Payment rules", "detail": "Uses a payment method not on the user's profile, amounts that don't sum to the exact price, or exceeds the per-method limits (<=1 certificate, <=1 credit card, <=3 gift cards).", "tasks": ["8"], "scope": "WIDESPREAD", "latent": false, "tag": "BEHAVIORAL"},
    {"id": "C", "name": "Cancellation eligibility", "detail": "Cancels without verifying flown-segment / the 4 eligibility conditions / the required reason.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "BEHAVIORAL"},
    {"id": "D", "name": "Modify-flight rules", "detail": "Basic-economy flights immutable, no origin/dest/trip-type change, cabin-change-if-not-flown, passenger count fixed, full flights list required.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "KNOWLEDGE"},
    {"id": "E", "name": "Compensation", "detail": "Wrong eligibility, wrong certificate amount, or proactive unsolicited offer.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "KNOWLEDGE"},
    {"id": "F", "name": "Confirm-before-write + one-call-at-a-time", "detail": "Weak model skips explicit confirmation before a DB write or batches a tool call with a user message.", "tasks": ["8"], "scope": "SYSTEMIC", "latent": false, "tag": "BEHAVIORAL"},
    {"id": "G", "name": "Error recovery", "detail": "Opaque tool errors (seat shortage, unavailable flight, payment) strand the agent instead of guiding the next turn.", "tasks": ["8"], "scope": "WIDESPREAD", "latent": false, "tag": "KNOWLEDGE"}
  ],
  "edits": [
    {"id": "E1", "title": "New calculate_baggage_allowance(user_id, cabin, num_passengers) compute tool", "files": ["tools/tools.py"], "lever": "CAPABILITY", "clusters": ["A"], "blast_radius": "BOUNDED", "verified": "Base+offset table checked against all 9 membership x cabin combos = policy table; additive READ tool, task 8 (0 bags) unchanged."},
    {"id": "E2", "title": "Enriched recovery errors in book_reservation (payment not on profile -> available list; low balance -> balance vs requested; amount mismatch -> exact total formula+target; seat shortage -> available count+options; unavailable -> status+next step)", "files": ["tools/tools.py"], "lever": "KNOWLEDGE", "clusters": ["B", "G"], "blast_radius": "BOUNDED", "verified": "Error-path-only; task 8 hit the seat error and now gets a richer message; success path byte-identical."},
    {"id": "E3", "title": "Literal slot-filling per-parameter docs on book_reservation", "files": ["tools/tools.py"], "lever": "KNOWLEDGE", "clusters": ["A", "B"], "blast_radius": "BOUNDED", "verified": "Docstring-only; encodes method-on-profile, amount-sums-to-total, nonfree formula, cabin/insurance enums."},
    {"id": "E4", "title": "Policy operating guide: goal+softness clause, golden-rules checklist, confirm-before-write worked example", "files": ["policy/policy.md"], "lever": "CONTRACT", "clusters": ["F"], "blast_radius": "MODERATE", "verified": "Reinforces behaviors task 8 already performs; all original rules retained verbatim."},
    {"id": "E5", "title": "Policy procedures/checklists + worked examples for booking/baggage, cancellation eligibility, modify rules, compensation", "files": ["policy/policy.md"], "lever": "KNOWLEDGE", "clusters": ["A", "B", "C", "D", "E"], "blast_radius": "MODERATE", "verified": "Each restates an existing policy rule (no invented rule, no broadened permission); constraint lines preserved."}
  ],
  "skipped": [
    {"title": "Silent server-side override of nonfree_baggages in book_reservation", "reason": "Would decouple from the agent's quoted payment amount and could create NEW payment-mismatch rejections on valid bookings; kept as a compute helper instead."},
    {"title": "In-code cancellation/modify eligibility guards", "reason": "cancel API lacks a reason arg and modify eligibility needs flown/route semantics; a deterministic guard risks false refusals. Enforced via policy checklists."}
  ],
  "techniques": ["compute tool for a derivable-but-error-prone quantity", "enriched actionable error returns", "literal per-parameter slot-filling docs", "ordered procedures + decision checklists + worked examples for a mid-capability reader", "softness/judgement clause", "constraint-preserving prompt augmentation"]
}
